UPDATE `gameobject` g
JOIN `gameobject_bak_405` b ON b.`guid` = g.`guid`
SET g.`spawntimesecsmin` = LEAST(b.`old_min`, GREATEST(5, b.`old_min` DIV 2)),
    g.`spawntimesecsmax` = LEAST(b.`old_max`, GREATEST(5, b.`old_max` DIV 2));
